import pandas as pd
import numpy as np

# Example 1: Timestamp scalar from max int64 seconds
try:
    ts = pd.DatetimeIndex(np.array([np.iinfo(np.int64).max], dtype='M8[s]'))[0]
    try:
        weekday_result = ts.weekday()
        probe("pd.DatetimeIndex(np.array([np.iinfo(np.int64).max], dtype='M8[s]'))[0].weekday()", weekday_result)
    except Exception as e:
        probe("pd.DatetimeIndex(np.array([np.iinfo(np.int64).max], dtype='M8[s]'))[0].weekday()", "__error__: " + type(e).__name__ + ": " + str(e))

